const input = $input.first();

// REQUIRED OPERATOR EDIT: keep empty until the exact tenant list is approved.
const ALLOWED_FACILITY_IDS = Object.freeze([]);
const MAX_SKEW_SECONDS = 300;
const MAX_BODY_BYTES = 4096;
const EVENT_TYPES = Object.freeze([
  'credential.created',
  'credential.verification_changed',
  'credential.expiry_due',
]);
const CREDENTIAL_TYPES = Object.freeze([
  'BLS', 'ACLS', 'PALS', 'NRP', 'TNCC', 'TCRN', 'code_red', 'code_blue',
  'fire_safety', 'infection_control', 'SCFHS_license', 'SCFHS_classification',
  'malpractice_insurance', 'employment_id', 'passport', 'iqama', 'visa',
  'driving_license', 'medical_license', 'custom',
]);
const EXPIRY_THRESHOLDS = Object.freeze([90, 60, 30, 15, 7, 1, 0]);

const reject = (statusCode, safeReason) => [{
  json: { precheckOk: false, statusCode, safeReason },
}];
const exactKeys = (value, expected) => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return false;
  const actual = Object.keys(value).sort();
  const wanted = [...expected].sort();
  return actual.length === wanted.length && actual.every((key, index) => key === wanted[index]);
};
const positiveInteger = (value) => Number.isSafeInteger(value) && value > 0;
const headerValue = (value) => Array.isArray(value) ? String(value[0] ?? '') : String(value ?? '');

const headers = Object.create(null);
for (const [name, value] of Object.entries(input.json?.headers ?? {})) {
  headers[name.toLowerCase()] = headerValue(value);
}
const contentType = headers['content-type'];
if (!/^application\/json(?:\s*;\s*charset=utf-8)?$/i.test(contentType)) {
  return reject(415, 'unsupported_content_type');
}
if (!input.binary?.data) return reject(400, 'missing_raw_body');
let rawBody;
try {
  rawBody = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch {
  return reject(400, 'missing_raw_body');
}
if (rawBody.length === 0 || rawBody.length > MAX_BODY_BYTES) {
  return reject(400, 'invalid_body_size');
}
const rawText = rawBody.toString('utf8');
if (!Buffer.from(rawText, 'utf8').equals(rawBody)) {
  return reject(400, 'invalid_utf8');
}

const timestamp = headers['x-health-credential-timestamp'];
const signatureHeader = headers['x-health-credential-signature'];
const eventHeader = headers['x-health-credential-event-id'];
const typeHeader = headers['x-health-credential-event-type'];
const idempotencyHeader = headers['idempotency-key'];
if (!/^\d{10}$/.test(timestamp)) return reject(401, 'invalid_signature');
const timestampSeconds = Number(timestamp);
const nowSeconds = Math.floor(Date.now() / 1000);
if (!Number.isSafeInteger(timestampSeconds) || Math.abs(nowSeconds - timestampSeconds) > MAX_SKEW_SECONDS) {
  return reject(401, 'expired_signature');
}
if (!/^sha256=[a-f0-9]{64}$/.test(signatureHeader)) {
  return reject(401, 'invalid_signature');
}

let envelope;
try {
  envelope = JSON.parse(rawText);
} catch {
  return reject(400, 'invalid_json');
}
if (!exactKeys(envelope, ['id', 'type', 'occurredAt', 'facilityId', 'data'])) {
  return reject(400, 'invalid_payload');
}
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(envelope.id)) {
  return reject(400, 'invalid_payload');
}
if (eventHeader !== envelope.id || idempotencyHeader !== envelope.id) {
  return reject(400, 'invalid_payload');
}
if (!EVENT_TYPES.includes(envelope.type) || typeHeader !== envelope.type) {
  return reject(400, 'invalid_payload');
}
if (typeof envelope.occurredAt !== 'string') return reject(400, 'invalid_payload');
let canonicalOccurredAt;
try {
  canonicalOccurredAt = new Date(envelope.occurredAt).toISOString();
} catch {
  return reject(400, 'invalid_payload');
}
if (canonicalOccurredAt !== envelope.occurredAt || !positiveInteger(envelope.facilityId)) {
  return reject(400, 'invalid_payload');
}

const data = envelope.data;
const baseDataValid = positiveInteger(data?.credentialId)
  && positiveInteger(data?.employeeId)
  && typeof data?.credentialType === 'string'
  && CREDENTIAL_TYPES.includes(data.credentialType);
if (!baseDataValid) return reject(400, 'invalid_payload');
if (envelope.type === 'credential.created') {
  if (!exactKeys(data, ['credentialId', 'employeeId', 'credentialType'])) {
    return reject(400, 'invalid_payload');
  }
} else if (envelope.type === 'credential.verification_changed') {
  if (!exactKeys(data, ['credentialId', 'employeeId', 'credentialType', 'isVerified'])
      || typeof data.isVerified !== 'boolean') {
    return reject(400, 'invalid_payload');
  }
} else if (!exactKeys(data, [
  'credentialId', 'employeeId', 'credentialType', 'expiryDate', 'dueInDays', 'thresholdDays',
])
  || typeof data.expiryDate !== 'string'
  || !/^\d{4}-\d{2}-\d{2}$/.test(data.expiryDate)
  || !Number.isSafeInteger(data.dueInDays)
  || !EXPIRY_THRESHOLDS.includes(data.thresholdDays)) {
  return reject(400, 'invalid_payload');
}

return [{
  json: {
    precheckOk: true,
    receiverConfigured: ALLOWED_FACILITY_IDS.length > 0,
    facilityAllowed: ALLOWED_FACILITY_IDS.includes(envelope.facilityId),
    id: envelope.id,
    type: envelope.type,
    occurredAt: envelope.occurredAt,
    facilityId: envelope.facilityId,
    signingInput: `${timestamp}.${rawText}`,
    providedSignature: signatureHeader.slice('sha256='.length),
  },
}];

const input = $input.first().json;
const actual = String(input.computedSignature ?? '').toLowerCase();
const expected = String(input.providedSignature ?? '').toLowerCase();
const left = actual.padEnd(64, '0').slice(0, 64);
const right = expected.padEnd(64, '0').slice(0, 64);
let difference = actual.length ^ expected.length;
for (let index = 0; index < 64; index += 1) {
  difference |= left.charCodeAt(index) ^ right.charCodeAt(index);
}
return [{
  json: {
    signatureValid: difference === 0,
    receiverConfigured: input.receiverConfigured === true,
    facilityAllowed: input.facilityAllowed === true,
    id: String(input.id),
    type: String(input.type),
    occurredAt: String(input.occurredAt),
    facilityId: Number(input.facilityId),
  },
}];
